# -*- Python -*-
# lit configuration for the HLS spatial verification plugin. The build-specific
# paths (opt, FileCheck, plugin) come from lit.site.cfg.py, generated by CMake.

import os

import lit.formats

config.name = "HLSSpatialVerify"
config.test_format = lit.formats.ShTest()
config.suffixes = [".ll"]
config.test_source_root = os.path.dirname(__file__)

# opt from the LLVM the plugin was built against; FileCheck may live outside
# the tools dir (e.g. libexec/llvm in some distributions).
path = [config.llvm_tools_dir, os.path.dirname(config.filecheck)]
config.environment["PATH"] = os.pathsep.join(path + [config.environment.get("PATH", os.environ.get("PATH", ""))])

config.substitutions.append(("%plugin", config.plugin))
# %hls-sv: run the printer; verdicts are written to stderr.
config.substitutions.append(
    ("%hls-sv",
     "opt -load-pass-plugin %s -passes='print<hls-spatial-verify>' "
     "-disable-output" % config.plugin))
